void init_GPIO(void){
    /* Enable GPIO clock */
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN;    
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOBEN;
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOCEN;

    GPIOA->MODER &= ~(GPIO_MODER_MODE5); // Clear mode bits for PA5
    GPIOA->MODER |= (GPIO_MODER_MODE5_0); // Set PA5 as output
    GPIOA->OTYPER &= ~(GPIO_OTYPER_OT5); // Set PA5 as push-pull
    GPIOA->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED5); // Set PA5 speed to low
    GPIOA->PUPDR &= ~(GPIO_PUPDR_PUPD5); // No pull-up, pull-down for PA5
    GPIOA->ODR &= ~(GPIO_ODR_OD5); // Set PA5 output to low

    GPIOB->MODER &= ~(GPIO_MODER_MODE5); // Clear mode bits for PB5
    GPIOB->MODER |= (GPIO_MODER_MODE5_0); // Set PB5 as output
    GPIOB->OTYPER &= ~(GPIO_OTYPER_OT5); // Set PB5 as push-pull
    GPIOB->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED5); // Set PB5 speed to low
    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD5); // No pull-up, pull-down for PB5
    GPIOB->ODR &= ~(GPIO_ODR_OD5); // Set PB5 output to low

    GPIOC->MODER &= ~(GPIO_MODER_MODE13); // Clear mode bits for PC13
    GPIOC->MODER &= ~(GPIO_MODER_MODE13_0); // Set PC13 as input
    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD13); // No pull-up, pull-down for PC13
}

void init_EXTI(void){
    /* Enable SYSCFG clock */
    RCC->APB2ENR &= ~(RCC_APB2ENR_SYSCFGEN); // Clear SYSCFGEN bit
    RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN;

    /* Configure EXTI line 13 for PC13 */
    SYSCFG->EXTICR[3] &= ~(SYSCFG_EXTICR4_EXTI13); // Clear EXTI13 bits
    SYSCFG->EXTICR[3] |= (SYSCFG_EXTICR4_EXTI13_PC); // Set EXTI13 to PC13

    /* Configure EXTI line 13 */
    EXTI->RTSR &= ~(EXTI_RTSR_TR13); // Disable rising edge trigger
    EXTI->FTSR |= EXTI_FTSR_TR13; // Trigger on falling edge

    EXTI->PR |= EXTI_PR_PR13; // Clear pending bit for EXTI line 13
    EXTI->IMR |= EXTI_IMR_IM13; // Unmask EXTI line 13

    /* Enable EXTI15_10 interrupt in NVIC */
    NVIC_EnableIRQ(EXTI15_10_IRQn);
}


void init_TIM(void){
    RCC->APB1ENR |= RCC_APB1ENR_TIM2EN; // Enable TIM2 clock
    TIM2->PSC = 16000 - 1; // Set prescaler to 16000 (assuming 16 MHz clock)
    TIM2->ARR = 1000 - 1; // Set auto-reload value
    TIM2->CRT = 0; // TIM2 counter reset

    TIM2->DIER |= TIM_DIER_UIE; // Enable update interrupt
    TIM2->CR1 |= TIM_CR1_DIR; // Set direction to upcounting
    TIM2->CR1 |= TIM_CR1_ARPE; // Enable auto-reload preload

    TIM2->SR &= ~(TIM_SR_UIF); // Clear update interrupt flag

    NVIC_EnableIRQ(TIM2_IRQn); // Enable TIM2 interrupt in NVIC
    TIM2->CR1 |= TIM_CR1_CEN; // Start TIM2
}

void EXTI15_10_IRQHandler(void){
    if(EXTI->PR & EXTI_PR_PR13){ // Check if EXTI line 13 triggered
        EXTI->PR |= EXTI_PR_PR13; // Clear pending bit for EXTI line 13

        update = 1; // Set update flag to indicate button press
    }
}
void TIM2_IRQHandler(void){
    if(TIM2->SR & TIM_SR_UIF){ // Check if update interrupt flag is set
        TIM2->SR &= ~(TIM_SR_UIF); // Clear update interrupt flag

        GPIOB->ODR ^= GPIO_ODR_OD5; // Toggle PB5 (LED)
    }
}



